'use client';

/*
 * priceosLogos — F54 (BUG-06).
 *
 * Full PRICEOS_LOGOS set: the sim.html 7484-7551 originals (58 figlet
 * renders; an earlier note here said 54 — miscount) plus the 22-logo
 * 2026-06-10 batch Brendon curated (branded-look and janky-at-10px
 * candidates were cut: Rammstein, Star Wars, Fender, Whimsy, Rozzo,
 * Bloody). 80 total. Pre-F54 the
 * React port had a hand-curated 6-logo subset inlined in PriceosModal;
 * BUG-06 flagged the gap because the rotation lost most of its variety.
 *
 * 2026-07-24 batch (+131, then Brendon's 15 cuts → 196 total). Swept
 * all 328 figlet fonts,
 * dropped the ones already in the pool (71 byte-identical renders, 12
 * name matches), the non-art junk fonts (binary / morse / hex / etc.),
 * the near-duplicate skeletons of fonts we already carry, the broken
 * renders (Ivrit reverses, Efti Piti drops letters, Mirror, Rotated),
 * and the six Brendon cut in 2026-06-10 — they stay cut, forever. Also
 * cut Small Braille and Def Leppard: Courier New has no Braille glyphs
 * so the art falls back to a proportional face and shears, and Def
 * Leppard is a band logo (same reason Rammstein / Star Wars went).
 *
 * Brendon then reviewed the whole 211 and cut 15 — Calvin S, Wet Letter,
 * Elite, AMC Neko, Chiseled, Cosmike, Dancing Font, Flower Power, Sweet,
 * THIS, Train, The Edge, Crazy, Bear, Fraktur (2026-07-24). Like the six
 * before them, THEY STAY CUT — never re-add on a future font sweep.
 *
 * The last 17 entries in `rare` are the big-face tier: fonts whose
 * single-line "PriceOS" ran 68-125 columns, so they are rendered with
 * "Price" and "OS" as two stacked figlet blocks, RIGHT-ALIGNED to a
 * shared right edge (Brendon, 2026-07-24). Stacking drops them to 43-87
 * columns — at the phone's 8px Courier the modal fits ~75 before
 * PriceosModal's rAF scale-to-fit engages, so 15 of the 17 render at
 * full size untouched and only Patorjk-HeX (79) and Doh (87) scale, to
 * 95% and 87%. They are taller in exchange: 12-36 rows against the
 * 6-12 of a normal entry, topping out at Caligraphy2's ~304px block.
 *
 * Tier organisation matches sim — common / middle / rare — but per
 * sim 7553-7555 the picker flattens all three into one pool with equal
 * probability per Brendon's APR 20 debug-phase request. The FLAT_LOGOS
 * export captures that flat pool; pickRandomLogo() is the single
 * caller-facing API.
 *
 * Strings are exactly as sim has them — multi-line ASCII art with
 * backslash escapes, embedded \\ and \n preserved. The trailing
 * `// Slant` etc. comments name each figlet font and stay for sim
 * traceability. DO NOT reformat or "clean up" the strings — the
 * trailing-space and escape patterns are what make the figlets render.
 *
 * Out of F54 scope: the full PRICEOS_CHANGELOG port (BUG-06 second
 * half). The 10-entry curated changelog inside PriceosModal stays as-is
 * for now; a later fix lifts the full ~100-entry log to its own module.
 */

export interface PriceosLogos {
    common: string[];
    middle: string[];
    rare: string[];
}

