/* Sim 7553-7555 + 7559: equal-probability flat pool. Tier weights
   are preserved on the object above for future "rare logos" UX, but
   the current debug-phase picker reads from the flattened union. */
export const FLAT_LOGOS: readonly string[] = [
    ...PRICEOS_LOGOS.common,
    ...PRICEOS_LOGOS.middle,
    ...PRICEOS_LOGOS.rare,
];

/** Sim 7556-7560 _pickPriceosLogo — random pick from the flat pool. */
export function pickRandomLogo(): string {
    return FLAT_LOGOS[Math.floor(Math.random() * FLAT_LOGOS.length)];
}

